// The breakdance routine's timeline for the video tools, read from the game's own clip windows
// (src/motion/breakClips.ts, generated by tools/motion/export_clips.py) and laid out as
// src/motion/breakdance.ts plays it: each move plays its window [from, to] and the next one starts
// its crossfade `FADE` seconds before that window ends. Re-recorded clips (new windows, new event
// times) move every camera set-up and every cut with them.
import { BREAK_CLIPS } from '../../../src/motion/breakClips.ts';

/** The routine's moves in order (src/motion/breakdance.ts ROUTINE) and their crossfade. */
export const ORDER = ['break_toprock', 'break_sixstep', 'break_spin', 'break_jumpspin', 'break_backflip', 'break_oneclaw'];
export const FADE = 0.25;

/**
 * Per move: `start` on the routine clock (seconds since B), `len` (its window), `ev` its clip
 * events as seconds into the move (event minus the window's start), `at(name)` the same on the
 * routine clock.
 */
export const MOVES = (() => {
  let start = 0;
  return ORDER.map((id, i) => {
    const c = BREAK_CLIPS[id];
    if (!c) throw new Error(`src/motion/breakClips.ts has no ${id}`);
    const len = c.to - c.from;
    const ev = Object.fromEntries(Object.entries(c.events).map(([k, v]) => [k, v - c.from]));
    const s0 = start;
    const m = {
      id,
      index: i,
      start: s0,
      len,
      ev,
      at(name) {
        if (!(name in ev)) throw new Error(`${id} has no event ${name}`);
        return s0 + ev[name];
      },
    };
    start += len - (i + 1 < ORDER.length ? FADE : 0);
    return m;
  });
})();

export const MOVE = Object.fromEntries(MOVES.map((m) => [m.id.replace('break_', ''), m]));
/** The routine's length, seconds. */
export const LENGTH = MOVES[MOVES.length - 1].start + MOVES[MOVES.length - 1].len;
